import json, os, sys, time, math, tempfile, hashlib, platform, resource, subprocess, datetime
t0 = time.monotonic(); ROOT = '/home/ryan/rule30-lab'
resource.setrlimit(resource.RLIMIT_AS, (1073741824, 1073741824))
def T(S): return S ^ ((S << 1) | (S << 2))
def P(R): return (T(1 + 2*R) - 1)//2
def U(S): return T(S) ^ 1
def build(ph, K):
    F = {1: ({3} if ph == 'p' else {1})}
    for k in range(1, K): F[k+1] = {g(x) for x in F[k] for g in (T, P, U)}
    return F
Fp, Fu = build('p', 12), build('u', 12)
rows = 0; bad = []
for S in range(1, 128):
    s = S.bit_length(); R = S; Rs = [S]
    for _ in range(s+3): R = T(R); Rs.append(R)
    for n in range(s, s+4):
        X = Rs[n] >> n
        assert X.bit_length() == s + n
        a = 'p' if (s + n) % 2 == 0 else 'u'
        k = math.ceil((s + n)/2)
        F = Fp if a == 'p' else Fu
        if X not in F[k]: bad.append((S, n))
        rows += 1
assert not bad and rows == 508
cpu = next((l.split(':',1)[1].strip() for l in open('/proc/cpuinfo').read().splitlines() if l.startswith('model name')), 'unknown')
src = open(__file__).read()
summary = {'S_range': [1, 127], 'n_offsets': [0, 1, 2, 3], 'rows': rows, 'mismatches': 0}
rec = {'experiment_id': '20260905_seam_frontier_membership', 'timestamp_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'git_commit': subprocess.check_output(['git','rev-parse','HEAD'], cwd=ROOT, text=True).strip(), 'question': 'problem1', 'hypothesis': 'X=T^n(S)>>n lies in O(a,k) with a=p iff s+n even, k=ceil((s+n)/2), for positive S and n>=bitlen(S).', 'backend': 'python-exact-integers', 'parameters': {'S_range': [1, 127], 'n_offsets': [0, 1, 2, 3], 'wall_limit_seconds': 120, 'address_space_bytes': 1073741824}, 'hardware': {'cpu_model': cpu, 'machine': platform.machine(), 'cpu_count': os.cpu_count(), 'peak_rss_kib': resource.getrusage(resource.RUSAGE_SELF).ru_maxrss}, 'software': {'python': sys.version, 'platform': platform.platform()}, 'runtime_seconds': time.monotonic()-t0, 'result_hashes': {'source_sha256': hashlib.sha256(src.encode()).hexdigest(), 'result_sha256': hashlib.sha256(json.dumps(summary, sort_keys=True, separators=(',', ':')).encode()).hexdigest()}, 'source_text': src, 'result_summary': summary, 'interpretation': 'Exact phase/k formula on all 508 rows; membership needs no alternation.', 'status': 'finite-exhaustive', 'proof_scope': 'All positive S<128, n in [s,s+3]; general claim by hand.', 'limitations': ['Small box only.']}
fd, tmp = tempfile.mkstemp(dir='/tmp', prefix='rec_', suffix='.tmp')
with os.fdopen(fd,'w') as f: json.dump(rec, f, sort_keys=True, indent=2); f.write(chr(10)); f.flush(); os.fsync(f.fileno())
os.replace(tmp, '/tmp/seam_member.json')
print('R4 membership pass')
